"""Exact before/after outputs. Content notes are editorial, never owner ratings."""
import sys,json,html
from pathlib import Path
old=json.loads(Path(sys.argv[1]).read_text());path=Path(sys.argv[2]);new=json.loads(path.read_text());e=lambda s:html.escape(str(s));lookup={(t['category'],t['question']):t for t in old['turns']}
rows=[]
for i,t in enumerate(new['turns'],1):
 before=lookup.get((t['category'],t['question']));b=(before.get('reply') or '被拦截：'+before.get('error','')) if before else '新增问题，无旧版实测对照'
 a=t.get('reply') or '被拦截：'+t.get('error','')
 rows.append(f'<article><div class="meta">第{i}题 · {e(t['category'])} · {e(t.get('evidencePhase','single_pass'))} · {e(t["mode"])} · {t["elapsedMs"]/1000:.1f}秒 · {t["modelCalls"]}次生成</div><h3>客户：{e(t["question"])}</h3><div class="pair"><div><strong>旧版实际回复</strong><p>{e(b)}</p></div><div><strong>本版实际回复</strong><p>{e(a)}</p></div></div><p class="meta">本机规则：{e(t["status"])}；方向：{e(t.get("trial",{}).get("receptionAction",{}).get("label","") if t.get("trial",{}).get("receptionAction") else "原试聊流程")}。规则允许显示不代表本人或客户认可。</p><details><summary>本版原始输出（含被拒绝的内容，不可直接发送）</summary><pre>{e(json.dumps(t.get("rawOutputs",[]),ensure_ascii=False,indent=2))}</pre></details></article>')
summary={'scope':new['scope'],'executionsTotal':new.get('executionsTotal',len(new['turns'])),'distinctQuestions':len(new['turns']),'modelCalls':new['modelCalls'],'localGuardAccepted':new['accepted'],'localGuardRejectedOrProviderError':new['rejected'],'pairedPriorTurns':sum((t['category'],t['question']) in lookup for t in new['turns']),'unseenQuestions':sum(t['category']=='新增未见问题' for t in new['turns']),'ownerLikenessAccepted':False,'independentCustomerSatisfactionMeasured':False,'realWechatCalls':0,'trainingPerformed':False}
(path.parent/'comparison-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
review=json.loads((path.parent/'editorial-review.json').read_text()) if (path.parent/'editorial-review.json').exists() else {'conclusion':'实际记录已生成，内容复核待完成。','findings':[]}
findings=''.join('<li>'+e(x)+'</li>' for x in review['findings'])
text=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>多场景整改前后实测</title><style>body{{font:16px/1.7 system-ui,sans-serif;color:#193d33;background:#f4f6f3;max-width:1100px;margin:30px auto;padding:0 18px}}article,.intro{{background:white;border:1px solid #d4ded6;padding:22px;border-radius:12px;margin:18px 0}}h1,h2,h3{{line-height:1.4}}.meta{{color:#586f65;font-size:14px}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:16px}}.pair>div{{padding:16px;border-radius:8px;background:#f2f2ed}}.pair>div+div{{background:#eaf3e6}}pre{{white-space:pre-wrap;overflow-wrap:anywhere}}@media(max-width:650px){{.pair{{grid-template-columns:1fr}}}}</style><h1>多场景整改 · 逐句前后对照</h1><div class="intro"><strong>{e(review['conclusion'])}</strong><p>本版分两次修订，实际执行{new.get('executionsTotal',len(new['turns']))}轮，调用本机千问{new['modelCalls']}次。下方{len(new['turns'])}道题采用各自最新记录，规则放行{new['accepted']}条，拦截或失败{new['rejected']}条。首轮36轮＋针对性复测14轮，原始两轮记录另存，未删失败。旧版配对{summary['pairedPriorTurns']}轮，新增未见问法{summary['unseenQuestions']}轮。两版均为真实本机模型输出，未补写或替换回复。</p><p>固定客户题，不是自主客户；没有独立满意度研究或店主口吻打分。没有真实微信发送、实际订单、支付、退款或模型训练。放行率不等于接待质量。没有核准商品事实，仍不能证明完整成交能力。</p><p>隐私、家常、情绪、身份与结束等聚焦回复只提供当前话题及表达参考，旧分支仍保留，之后回题时可以检索；避免把上轮荐款带进闲聊。</p><ul>{findings}</ul></div>{''.join(rows)}</html>'''
(path.parent/'整改前后实测报告.html').write_text(text);print(json.dumps(summary,ensure_ascii=False))
